      buffer.putUint8(130);
      writeValue(buffer, value.index);
    } else if (value is GuardrailsMessage) {
      buffer.putUint8(131);
      writeValue(buffer, value.index);
    } else if (value is AvailabilityStatusMessage) {
      buffer.putUint8(132);
      writeValue(buffer, value.index);
    } else if (value is CapabilityMessage) {
      buffer.putUint8(133);
      writeValue(buffer, value.index);
    } else if (value is SamplingKindMessage) {
      buffer.putUint8(134);
      writeValue(buffer, value.index);
    } else if (value is ToolCallingModeMessage) {
      buffer.putUint8(135);
      writeValue(buffer, value.index);
    } else if (value is ReasoningLevelMessage) {
      buffer.putUint8(136);
      writeValue(buffer, value.index);
    } else if (value is TranscriptPolicyMessage) {
      buffer.putUint8(137);
      writeValue(buffer, value.index);
    } else if (value is FeedbackSentimentMessage) {
      buffer.putUint8(138);
      writeValue(buffer, value.index);
    } else if (value is FeedbackIssueCategoryMessage) {
