      writeValue(buffer, value.index);
    } else if (value is TranscriptEntryKindMessage) {
      buffer.putUint8(140);
      writeValue(buffer, value.index);
    } else if (value is SegmentKindMessage) {
      buffer.putUint8(141);
      writeValue(buffer, value.index);
    } else if (value is BuiltInToolMessage) {
      buffer.putUint8(142);
      writeValue(buffer, value.index);
    } else if (value is ImageInputKindMessage) {
      buffer.putUint8(143);
      writeValue(buffer, value.index);
    } else if (value is ModelConfigMessage) {
      buffer.putUint8(144);
      writeValue(buffer, value.encode());
    } else if (value is AvailabilityMessage) {
      buffer.putUint8(145);
      writeValue(buffer, value.encode());
    } else if (value is ModelInfoMessage) {
      buffer.putUint8(146);
      writeValue(buffer, value.encode());
